import { balanceDue } from './payments.js';
import { daysBetween } from './dates.js';
import { roundCents } from './money.js';

/**
 * Get overdue invoices as of a given date.
 * @param {Array<object>} invoices - Array of invoice objects
 * @param {string} asOf - Date in YYYY-MM-DD format
 * @returns {Array<{ number: string, customerId: string, dueDate: string, daysOverdue: number, due: number }>}
 */
export function overdueInvoices(invoices, asOf) {
  const overdue = invoices
    .filter(inv => ['issued', 'partially_paid'].includes(inv.status))
    .filter(inv => inv.dueDate < asOf)
    .map(inv => ({
      number: inv.number,
      customerId: inv.customerId,
      dueDate: inv.dueDate,
      daysOverdue: daysBetween(inv.dueDate, asOf),
      due: balanceDue(inv),
    }))
    .sort((a, b) => b.daysOverdue - a.daysOverdue);

  return overdue;
}

/**
 * Get VAT summary over invoices.
 * @param {Array<object>} invoices - Array of invoice objects
 * @returns {Array<{ rate: number, base: number, vat: number }>}
 */
export function vatSummary(invoices) {
  const vatMap = {};

  for (const invoice of invoices) {
    // Only include issued, partially_paid, or paid invoices
    if (!['issued', 'partially_paid', 'paid'].includes(invoice.status)) {
      continue;
    }

    // Process each line in the invoice
    for (const line of invoice.lines) {
      const rate = line.vatRate;
      const lineTotal = line.qty * line.unitPrice;
      const discount = lineTotal * (line.discountPercent ?? 0) / 100;
      const base = lineTotal - discount;
      const vat = roundCents(base * rate / 100);

      if (!vatMap[rate]) {
        vatMap[rate] = { rate, base: 0, vat: 0 };
      }

      vatMap[rate].base += base;
      vatMap[rate].vat += vat;
    }
  }

  // Convert map to array and sort by rate descending
  return Object.values(vatMap).sort((a, b) => b.rate - a.rate);
}

/**
 * Calculate late fee for an invoice.
 * @param {object} invoice - An invoice object
 * @param {string} asOf - Date in YYYY-MM-DD format
 * @returns {number}
 */
export function lateFee(invoice, asOf) {
  // Return 0 if invoice is not issued or partially_paid
  if (!['issued', 'partially_paid'].includes(invoice.status)) {
    return 0;
  }

  // Return 0 if not overdue (dueDate is on or after asOf)
  if (invoice.dueDate >= asOf) {
    return 0;
  }

  // Calculate days overdue
  const daysOverdue = daysBetween(invoice.dueDate, asOf);

  // Calculate amount due
  const due = balanceDue(invoice);

  // Calculate late fee: 0.04% per day = 0.0004
  const fee = roundCents(due * 0.0004 * daysOverdue);

  return fee;
}

