import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, issueInvoice } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';
import { overdueInvoices, vatSummary, lateFee } from '../src/reports.js';

test('overdueInvoices returns empty array when no invoices', () => {
  const result = overdueInvoices([], '2026-10-15');
  assert.deepEqual(result, []);
});

test('overdueInvoices returns empty array when no overdue invoices', () => {
  const invResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-10',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET30',
  });

  const inv = issueInvoice(invResult.value, []).value;
  // Due date is 2026-11-09

  const result = overdueInvoices([inv], '2026-11-08');
  assert.deepEqual(result, []);
});

test('overdueInvoices includes issued invoice past due date', () => {
  const invResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  });

  const inv = issueInvoice(invResult.value, []).value;
  // Due date is 2026-10-15

  const result = overdueInvoices([inv], '2026-10-20');
  assert.equal(result.length, 1);
  assert.equal(result[0].number, 'INV-2026-0001');
  assert.equal(result[0].customerId, 'C-001');
  assert.equal(result[0].dueDate, '2026-10-15');
  assert.equal(result[0].daysOverdue, 5);
});

test('overdueInvoices includes partially_paid invoice past due date', () => {
  const invResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  });

  const invIssued = issueInvoice(invResult.value, []).value;
  const invPartial = recordPayment(invIssued, { amount: 10000, date: '2026-10-10' }).value;

  const result = overdueInvoices([invPartial], '2026-10-20');
  assert.equal(result.length, 1);
  assert.equal(result[0].number, 'INV-2026-0001');
  assert.equal(result[0].daysOverdue, 5);
  assert.ok(result[0].due > 0);
});

test('overdueInvoices excludes draft invoices', () => {
  const invResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  const result = overdueInvoices([invResult.value], '2026-10-20');
  assert.deepEqual(result, []);
});

test('overdueInvoices excludes paid invoices', () => {
  const invResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  });

  const invIssued = issueInvoice(invResult.value, []).value;
  const invPaid = recordPayment(invIssued, { amount: 48854, date: '2026-10-10' }).value;

  const result = overdueInvoices([invPaid], '2026-10-20');
  assert.deepEqual(result, []);
});

test('overdueInvoices sorts by most overdue first', () => {
  const inv1Result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  });

  const inv2Result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-05',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  });

  const inv1 = issueInvoice(inv1Result.value, []).value;
  const inv2 = issueInvoice(inv2Result.value, ['INV-2026-0001']).value;

  const result = overdueInvoices([inv2, inv1], '2026-10-25');
  assert.equal(result.length, 2);
  assert.equal(result[0].dueDate, '2026-10-15'); // More overdue
  assert.equal(result[1].dueDate, '2026-10-19'); // Less overdue
  assert.equal(result[0].daysOverdue, 10);
  assert.equal(result[1].daysOverdue, 6);
});

test('overdueInvoices returns correct due amount for partially paid invoice', () => {
  const invResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  });

  const invIssued = issueInvoice(invResult.value, []).value;
  const invPartial = recordPayment(invIssued, { amount: 10000, date: '2026-10-10' }).value;

  const result = overdueInvoices([invPartial], '2026-10-20');
  assert.equal(result.length, 1);
  assert.equal(result[0].due, 48854 - 10000);
});

test('overdueInvoices returns zero due for fully paid invoice before becoming overdue', () => {
