  const invPaid = recordPayment(invIssued, { amount: 48854, date: '2026-10-10' }).value;

  // Paid invoices are excluded entirely
  const result = overdueInvoices([invPaid], '2026-10-20');
  assert.equal(result.length, 0);
});

