    terms: 'NET14',
  });

  const inv = issueInvoice(invResult.value, []).value;
  const invoices = [inv];
  const originalLength = invoices.length;

  overdueInvoices(invoices, '2026-10-20');

  assert.equal(invoices.length, originalLength);
});

