test('vatSummary with single issued invoice', () => {
  const invResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  const inv = issueInvoice(invResult.value, []).value;
  const result = vatSummary([inv]);

  assert.equal(result.length, 1);
  assert.equal(result[0].rate, 21);
  // Line: 5 * 8500 = 42500, discount 5% = 2125, base = 40375, VAT = 8478.75 → 8479
  assert.equal(result[0].base, 40375);
  assert.equal(result[0].vat, 8479);
});

