test('vatSummary with multiple VAT rates', () => {
  const invResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 }, // 21% VAT
      { sku: 'PRINT-A4', qty: 100 }, // 9% VAT
      { sku: 'WORKSHOP-DAY', qty: 1 }, // 0% VAT
    ],
  });

  const inv = issueInvoice(invResult.value, []).value;
  const result = vatSummary([inv]);

  assert.equal(result.length, 3);
  // Sorted by rate descending
  assert.equal(result[0].rate, 21);
  assert.equal(result[1].rate, 9);
  assert.equal(result[2].rate, 0);
});

