    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 }, // 21% VAT
      { sku: 'DEV-HOUR', qty: 3 }, // 21% VAT
    ],
  });

  const inv = issueInvoice(invResult.value, []).value;
  const result = vatSummary([inv]);

  assert.equal(result.length, 1);
  assert.equal(result[0].rate, 21);
  // Line 1: 5 * 8500 = 42500, discount 5% = 2125, base = 40375
  // Line 2: 3 * 9500 = 28500, discount 5% = 1425, base = 27075
  // Total base: 40375 + 27075 = 67450
  assert.equal(result[0].base, 67450);
});

