  const inv2 = issueInvoice(inv2Result.value, ['INV-2026-0001']).value;

  // Both overdue by 10 days on 2026-10-25
  const fee1 = lateFee(inv1, '2026-10-25');
  const fee2 = lateFee(inv2, '2026-10-25');

  // inv2 has a higher amount due (no discount), so fee2 > fee1
  assert.ok(fee2 > fee1);
});
